/*
 * writing-phrases.js — the phrase bank for writing: #/writing/phrases[/<group>].
 *
 * Data: LM.PHRASES from the phrase bank source (generated by the build, loaded only when the bank is opened).
 * Phrases are grouped by function (opinion, counter-argument, …).
 *
 *   - filters: level (B1 / B2 / C1) with an "up to this level" switch, register, genre, favorites only,
 *   - search in both languages, also without accents (search folding),
 *   - groups as sections with anchors, a group list at the side (computer) or a horizontal chip bar (phone),
 *   - a phrase: the phrase in bold, the translation under it, level and register as text, an expandable example and note,
 *   - actions: Copy, "Add to My words" (a basic card in the "My words" deck), a star (favorites per profile, slm.phrases).
 *
 *   LM.writingPhrases.render(view, route)   LM.writingPhrases.load() → Promise z { groups }
 *   LM.writingPhrases.forTrainer(genre, examId) → [{ group, phrases }] for the panel in the writing trainer
 */
window.LM = window.LM || {};

(function (LM) {
  "use strict";

  const U = LM.utils;
  const el = U.el;
  const HASH = "#/writing/phrases";

  const LEVELS = ["B1", "B2", "C1"];
  const REGISTERS = { formal: "Formal", neutral: "Neutral", informal: "Informal" };
  const GENRES = { email: "Email", letter: "Letter", blog: "Blog", forum: "Forum", essay: "Essay", article: "Article", review: "Review", report: "Report", proposal: "Proposal", story: "Story" };
  // Phrase level in the trainer = the level of the exam in the registry (all levels when it has none)
  function examLevel(examId) { const e = ((LM.EXAM_REGISTRY || {}).exams || []).find(function (x) { return x.id === examId; }); return e && e.level ? e.level : null; }

  const state = { level: "all", upTo: true, register: "all", genre: "all", query: "", starred: false };
  let loading = null;

  function pd() { return LM.profileData; }
  function hasProfile() { return !!(LM.app && LM.app.getActiveProfile && LM.app.getActiveProfile()); }
  function fold(s) { return LM.searchLogic && LM.searchLogic.fold ? LM.searchLogic.fold(String(s)) : String(s).toLowerCase(); }

  /** Loads the bank (once). */
  function load() {
    if (LM.PHRASES) return Promise.resolve(LM.PHRASES);
    if (loading) return loading;
    loading = LM.loadModule("data/phrases.js").then(function () { return LM.PHRASES || null; }, function (err) {
      console.warn((err && err.message) + " — run: npm run build");
      loading = null;
      return null;
    });
    return loading;
  }

  /** A phrase to insert / copy: without the final ellipsis (ellipses inside stay as slots for the rest of the sentence). */
  function plain(en) { return String(en).replace(/\s*…\s*$/, "").replace(/\s+/g, " ").trim(); }

  function genresOf(group, phrase) { return phrase.genres || group.genres; }

  /** Phrases that fit the genre and the exam level, grouped (panel in the writing trainer). */
  function forTrainer(genre, examId) {
    const data = LM.PHRASES;
    if (!data) return [];
    const max = LEVELS.indexOf(examLevel(examId)) !== -1 ? LEVELS.indexOf(examLevel(examId)) : LEVELS.length - 1;
    const out = [];
    data.groups.forEach(function (g) {
      const list = g.phrases.filter(function (p) { return LEVELS.indexOf(p.level) <= max && genresOf(g, p).indexOf(genre) !== -1; });
      if (list.length) out.push({ group: g, phrases: list });
    });
    return out;
  }

  function matches(g, p) {
    if (state.level !== "all") {
      const i = LEVELS.indexOf(p.level), want = LEVELS.indexOf(state.level);
      if (state.upTo ? i > want : i !== want) return false;
    }
    if (state.register !== "all" && p.register !== state.register) return false;
    if (state.genre !== "all" && genresOf(g, p).indexOf(state.genre) === -1) return false;
    if (state.starred && starred().indexOf(p.id) === -1) return false;
    const q = fold(state.query.trim());
    if (q && fold(p.en + " " + p.pl + " " + (p.example || "")).indexOf(q) === -1) return false;
    return true;
  }

  function starred() { return pd() ? pd().starredPhrases() : []; }

  // ---------- actions ----------

  function say(text) { LM.ui.toast({ text: text, icon: "check" }); }

  function copyText(text) {
    function fallback() {
      const tmp = el("textarea", { value: text });
      tmp.style.position = "fixed";
      tmp.style.opacity = "0";
      document.body.appendChild(tmp);
      tmp.select();
      let ok = false;
      try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
      tmp.remove();
      say(ok ? "Copied: " + text : "Could not copy – select the text and press Ctrl+C");
    }
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(function () { say("Copied: " + text); }, fallback);
    else fallback();
  }

  // ---------- view ----------

  function render(view, route) {
    document.title = "Phrase bank · Writing · " + LM.APP.appTitle;
    view.appendChild(LM.ui.breadcrumbs([{ label: "Writing", href: LM.writing.HASH }, { label: "Phrase bank" }]));
    view.appendChild(LM.writing.head("Phrase bank for writing", "Phrases by function, from simple to formal. Choose a level, register and genre, copy a phrase or save it for review."));
    const body = el("div", { class: "zw-root" }, el("p", { class: "tool-note", role: "status", text: "Loading phrases…" }));
    view.appendChild(body);
    load().then(function (data) {
      if (!view.contains(body)) return;
      body.replaceChildren();
      if (!data) { body.appendChild(el("p", { class: "tool-note", text: "Could not load the phrase bank. Run: npm run build." })); return; }
      build(body, data, route && route.group);
    });
  }

  function build(root, data, focusGroup) {
    const count = el("p", { class: "journal-count", "aria-live": "polite" });
    const nav = el("nav", { class: "zw-nav", "aria-label": "Phrase groups" });
    const groupsBox = el("div", { class: "zw-groups" });

    // filters
    const levelSel = select("zw-level", "Level", [["all", "All"]].concat(LEVELS.map(function (l) { return [l, l]; })), state.level, function (v) { state.level = v; upTo.disabled = v === "all"; paint(); });
    const upTo = el("input", { type: "checkbox", id: "zw-upto", checked: state.upTo, disabled: state.level === "all", onchange: function () { state.upTo = upTo.checked; paint(); } });
    const regSel = select("zw-reg", "Register", [["all", "All"]].concat(Object.keys(REGISTERS).map(function (k) { return [k, REGISTERS[k]]; })), state.register, function (v) { state.register = v; paint(); });
    const genSel = select("zw-genre", "Genre", [["all", "All"]].concat(Object.keys(GENRES).map(function (k) { return [k, GENRES[k]]; })), state.genre, function (v) { state.genre = v; paint(); });
    const search = el("input", { id: "zw-q", class: "field", type: "search", value: state.query, placeholder: "Search the phrases…", autocomplete: "off", oninput: function () { state.query = search.value; paint(); } });
    const star = el("input", { type: "checkbox", id: "zw-star", checked: state.starred, onchange: function () { state.starred = star.checked; paint(); } });
    root.appendChild(el("div", { class: "journal-filters zw-filters", role: "search" }, [
      el("div", { class: "form-field is-grow" }, [el("label", { class: "field-label", for: "zw-q", text: "Search" }), search]),
      el("div", { class: "form-field" }, [el("label", { class: "field-label", for: "zw-level", text: "Level" }), levelSel]),
      el("div", { class: "form-field" }, [el("label", { class: "field-label", for: "zw-reg", text: "Register" }), regSel]),
      el("div", { class: "form-field" }, [el("label", { class: "field-label", for: "zw-genre", text: "Genre" }), genSel])
    ]));
    root.appendChild(el("div", { class: "zw-checks" }, [
      el("div", { class: "fc-check" }, [upTo, el("label", { for: "zw-upto", text: "up to this level (easier ones too)" })]),
      el("div", { class: "fc-check" }, [star, el("label", { for: "zw-star", text: "Favorites only" })])
    ]));
    root.appendChild(count);
    root.appendChild(el("div", { class: "zw-layout" }, [nav, groupsBox]));

    function select(id, label, options, value, onchange) {
      const s = el("select", { id: id, class: "field", onchange: function () { onchange(s.value); } },
        options.map(function (o) { return el("option", { value: o[0], selected: o[0] === value, text: o[1] }); }));
      return s;
    }

    function phraseItem(g, p) {
      const isStar = starred().indexOf(p.id) !== -1;
      const label = plain(p.en);
      const starBtn = el("button", { type: "button", class: "btn btn-link btn-small zw-star" + (isStar ? " is-on" : ""), "aria-pressed": isStar ? "true" : "false",
        "aria-label": (isStar ? "Remove from favorites: " : "Add to favorites: ") + label,
        onclick: function () {
          if (!hasProfile()) { LM.app.withProfile("Favorite phrases are saved in a profile.", function () { starBtn.click(); }); return; }
          pd().togglePhraseStar(p.id);
          paint(true);
          const again = root.querySelector('[data-pid="' + p.id + '"] .zw-star');
          if (again) again.focus();
        } }, [LM.icon("star", { size: 16 }), isStar ? " Favorite" : " Favorites"]);
      const details = p.example || p.note ? el("details", { class: "zw-more" }, [
        el("summary", { text: "Example and note" }),
        p.example ? el("p", { class: "zw-example", lang: LM.APP.targetLang }, [el("span", { class: "review-label", text: "Example: " }), p.example]) : null,
        p.note ? el("p", { class: "zw-note" }, [el("span", { class: "review-label", text: "Note: " }), p.note]) : null
      ]) : null;
      return el("li", { class: "card zw-phrase", "data-pid": p.id }, [
        el("div", { class: "zw-text" }, [
          el("p", { class: "zw-en", lang: LM.APP.targetLang, text: p.en }),
          el("p", { class: "zw-gloss", text: p.pl }),
          el("p", { class: "zw-chips" }, [
            el("span", { class: "chip", text: "Level " + p.level }),
            el("span", { class: "chip", text: REGISTERS[p.register] })
          ]),
          details
        ]),
        el("div", { class: "zw-actions" }, [
          el("button", { type: "button", class: "btn btn-secondary btn-small", "aria-label": "Copy: " + label, onclick: function () { copyText(label); } }, LM.ui.withIcon("copy", "Copy")),
          LM.words && LM.words.addPhrase ? el("button", { type: "button", class: "btn btn-secondary btn-small", "aria-label": "Add to My words: " + label,
            onclick: function () { LM.words.addPhrase({ en: p.en, pl: p.pl, example: p.example, route: HASH, title: "Phrase bank" }); } }, LM.ui.withIcon("layers", "Add to My words")) : null,
          starBtn
        ])
      ]);
    }

    function paint(keepScroll) {
      const y = window.scrollY;
      groupsBox.replaceChildren();
      nav.replaceChildren();
      let total = 0, shown = 0;
      const navItems = [];
      data.groups.forEach(function (g) {
        total += g.phrases.length;
        const list = g.phrases.filter(function (p) { return matches(g, p); });
        shown += list.length;
        if (!list.length) return;
        navItems.push(el("li", null, el("a", { href: HASH + "/" + g.id, onclick: function (ev) { ev.preventDefault(); const t = document.getElementById("zw-" + g.id); if (t) { t.scrollIntoView({ block: "start" }); t.focus({ preventScroll: true }); } } }, [g.label, " ", el("span", { class: "num zw-n", text: String(list.length) })])));
        groupsBox.appendChild(el("section", { class: "zw-group", id: "zw-" + g.id, tabindex: "-1", "aria-labelledby": "zw-h-" + g.id }, [
          el("h2", { class: "section-title", id: "zw-h-" + g.id, text: g.label }),
          g.description ? el("p", { class: "tool-note", text: g.description }) : null,
          el("ul", { class: "zw-list" }, list.map(function (p) { return phraseItem(g, p); }))
        ]));
      });
      count.textContent = "Phrases: " + shown + " of " + total + (state.starred && !hasProfile() ? " (favorites need a profile)" : "");
      if (!shown) groupsBox.appendChild(LM.ui.emptyState({ art: "no-results", title: state.starred ? "You have no favorite phrases that match the filters yet. Click “Favorites” next to a phrase." : "No phrases match the filters." }));
      nav.appendChild(el("ul", { class: "zw-nav-list" }, navItems));
      if (keepScroll) window.scrollTo(0, y);
    }
    paint();
    if (focusGroup) { const t = document.getElementById("zw-" + focusGroup); if (t) setTimeout(function () { t.scrollIntoView({ block: "start" }); }, 0); }
  }

  LM.writingPhrases = { render: render, load: load, forTrainer: forTrainer, plain: plain, LEVELS: LEVELS, REGISTERS: REGISTERS, GENRES: GENRES };
})(window.LM);
